input.content:
/**
 * Whitespace classification, split the same way CPython splits it.
 *
 * Two distinct notions are involved when `float(str)` runs, and conflating them
 * is the single easiest way to get this port wrong:
 *
 *   1. `Py_UNICODE_ISSPACE` — consulted only for code points >= 0x7F, while the
 *      string is normalised to ASCII. U+00A0, U+2028, U+3000 and friends live
 *      here.
 *   2. `Py_ISSPACE` — plain ASCII whitespace, used by the numeric scanner to
 *      trim the already-normalised buffer. Only \t \n \v \f \r and space.
 *
 * Because the normaliser copies every code point below 0x7F through untouched,
 * the C0 separators 0x1C..0x1F are *not* whitespace to `float()`, even though
 * `str.strip()` happens to remove them. Verified against the reference build:
 * "\x1c1.5" is rejected while "\x0b1.5" parses as 1.5.
 */

/** Code points >= 0x7F for which `Py_UNICODE_ISSPACE` is true. */
const UNICODE_SPACES = new Set([
  0x0085, // NEL
  0x00a0, // NO-BREAK SPACE
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

/**
 * `Py_UNICODE_ISSPACE`, restricted to the range the normaliser actually asks
 * about. U+180E, U+200B and U+FEFF are deliberately absent — Unicode 6.3 moved
 * U+180E out of the space category, and the other two never were spaces.
 */
export function isUnicodeSpace(codePoint) {
  return UNICODE_SPACES.has(codePoint);
}

/** `Py_ISSPACE`: \t \n \v \f \r and space. Nothing else. */
export function isAsciiSpace(codePoint) {
  return codePoint === 0x20 || (codePoint >= 0x09 && codePoint <= 0x0d);
}

/** Trim `Py_ISSPACE` characters from both ends of an ASCII-normalised string. */
export function stripAsciiSpace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isAsciiSpace(text.charCodeAt(start))) start += 1;
  while (end > start && isAsciiSpace(text.charCodeAt(end - 1))) end -= 1;
  return text.slice(start, end);
}

