input.content:
/**
 * `Py_UNICODE_TODECIMAL` — the decimal value of a Unicode digit.
 *
 * CPython's `float()` accepts any character carrying a decimal digit value, not
 * just ASCII: "١٢٣" parses as 123.0 and "1.5e١٠" as 15000000000.0. That set is
 * exactly general category Nd, which the engine can test natively via
 * `\p{Nd}`, so no digit table needs to be shipped or maintained here.
 *
 * Recovering the *value* takes one extra step. Nd code points always appear as
 * runs of ten consecutive points ordered 0..9, but distinct runs can sit flush
 * against each other — U+1D7CE..U+1D7D7 (bold) is immediately followed by
 * U+1D7D8..U+1D7E1 (double-struck). Walking backwards to the nearest non-Nd
 * point would therefore sail past the start of the block. Instead we find the
 * maximal contiguous Nd run, whose length is always a multiple of ten, and take
 * the aligned group of ten containing the character.
 */

const ND = /\p{Nd}/u;

/** Generous bound; the longest contiguous Nd run in Unicode is 50 points. */
const MAX_RUN_SCAN = 512;

/** True when `codePoint` is in general category Nd. */
export function isDecimalDigit(codePoint) {
  return codePoint >= 0 && codePoint <= 0x10ffff && ND.test(String.fromCodePoint(codePoint));
}

/**
 * Decimal value of `codePoint` in 0..9, or -1 when it carries none.
 * ASCII is short-circuited because it is the overwhelmingly common case.
 */
export function decimalValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (!isDecimalDigit(codePoint)) return -1;

  let runStart = codePoint;
  for (let i = 0; i < MAX_RUN_SCAN && runStart > 0; i += 1) {
    if (!isDecimalDigit(runStart - 1)) break;
    runStart -= 1;
  }

  const blockStart = runStart + Math.floor((codePoint - runStart) / 10) * 10;
  return codePoint - blockStart;
}

