/**
 * `str.isprintable()` for a single code point.
 *
 * CPython calls a character non-printable when its general category is one of
 * Cc, Cf, Cs, Co, Cn, Zl, Zp or Zs — with U+0020 carved out as printable even
 * though it is Zs. `\p{C}` covers the whole C group in one escape, so the test
 * reduces to two property classes plus that one exception.
 *
 * This is what decides how `repr()` renders a character: U+00A0 (Zs) comes out
 * as \xa0 and U+FEFF (Cf) as ﻿, while "é" and "日" are emitted literally.
 */

const NON_PRINTABLE = /[\p{C}\p{Zl}\p{Zp}\p{Zs}]/u;

export function isPrintableCodePoint(codePoint) {
  if (codePoint === 0x20) return true; // space is printable, other Zs are not
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

