/**
 * The handful of Python exception shapes this program can raise, carrying the
 * name that a traceback would print alongside the message.
 */

export class PyError extends Error {
  constructor(pyType, message) {
    super(message);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = message;
  }
}

/** `ValueError` — raised by the JSON encoder on nan/inf, and by `float()`. */
