/**
 * `repr()` of a Python float — i.e. `PyOS_double_to_string(v, 'r', 0,
 * Py_DTSF_ADD_DOT_0)`.
 *
 * The digits themselves are the shortest decimal string that round-trips back
 * to the same double. ECMAScript specifies exactly that for
 * `Number.prototype.toExponential()` with no argument ("f is as small as
 * possible"), so the engine's own converter supplies them and no Grisu/Ryu
 * implementation is needed here.
 *
 * What does have to be rebuilt is CPython's *layout*, which differs from
 * `String(number)` on all three axes:
 *
 *   - the fixed/scientific cutoff is `decpt <= -4 || decpt > 16`, whereas
 *     JavaScript switches at 1e21 and 1e-7. So 1e16 prints as "1e+16" (JS:
 *     "10000000000000000") and 1e-5 as "1e-05" (JS: "0.00001").
 *   - fixed-point output always carries a fractional part, so integral values
 *     gain a trailing ".0" — "1.0", "100.0", "9007199254740992.0".
 *   - exponents are signed and zero-padded to at least two digits: "e-05",
 *     "e+16", "e+308". JavaScript writes "e-5" and "e+16".
 *
 * `Py_DTSF_ADD_DOT_0` applies to fixed-point only, which is why 1e16 is
 * "1e+16" rather than "1.0e+16".
 */

/** `decpt` values outside this window force scientific notation. */
const MIN_FIXED_DECPT = -3; // decpt <= -4 => scientific
const MAX_FIXED_DECPT = 16; // decpt >  16 => scientific

const EXPONENTIAL_FORM = /^(\d)(?:\.(\d+))?e([+-]\d+)$/;

/**
 * Shortest round-trip digits of a finite, non-negative double, expressed as a
 * digit string plus CPython's `decpt` (the count of digits that precede the
 * decimal point in fixed-point layout).
 */
function shortestDigits(value) {
  const match = EXPONENTIAL_FORM.exec(value.toExponential());
  if (match === null) {
    // Unreachable for finite input: toExponential() is specified to produce
    // this shape. Guarded so a violation surfaces loudly instead of silently
    // formatting the wrong number.
    throw new Error(`unexpected toExponential() output for ${value}`);
  }
  const digits = match[1] + (match[2] ?? '');
  return { digits, decpt: Number.parseInt(match[3], 10) + 1 };
}

function formatFixed(digits, decpt) {
  if (decpt <= 0) return `0.${'0'.repeat(-decpt)}${digits}`;
  if (decpt >= digits.length) return `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  return `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
}

function formatScientific(digits, decpt) {
  const exponent = decpt - 1;
  const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
  const sign = exponent < 0 ? '-' : '+';
  return `${mantissa}e${sign}${String(Math.abs(exponent)).padStart(2, '0')}`;
}

/**
 * Render `value` the way `repr(float)` would.
 *
 * Non-finite input yields Python's spellings — "nan", "inf", "-inf". NaN has no
 * sign in Python: `float('-nan')` reprs as "nan".
 */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Number.POSITIVE_INFINITY) return 'inf';
  if (value === Number.NEGATIVE_INFINITY) return '-inf';

  // Object.is pins down -0.0, which must print as "-0.0".
  const negative = value < 0 || Object.is(value, -0);
  const { digits, decpt } = shortestDigits(Math.abs(value));

  const scientific = decpt < MIN_FIXED_DECPT || decpt > MAX_FIXED_DECPT;
  const body = scientific ? formatScientific(digits, decpt) : formatFixed(digits, decpt);

  return negative ? `-${body}` : body;
}

