/**
 * `float(str)` — CPython's string-to-double conversion, reproduced stage by
 * stage.
 *
 * The pipeline is:
 *
 *   1. `_PyUnicode_TransformDecimalAndSpaceToASCII` normalises the text. Code
 *      points below 0x7F pass through untouched; above that, Unicode spaces
 *      collapse to " " and Nd digits fold to their ASCII equivalent. Anything
 *      else survives verbatim and will fail the grammar.
 *   2. `_Py_string_to_number_with_underscores` validates PEP 515 underscores
 *      and strips them.
 *   3. `_PyOS_ascii_strtod` trims ASCII whitespace and scans the number,
 *      accepting inf/infinity/nan case-insensitively.
 *
 * Order matters. Because the transform runs first, "١_٢" is legal (it becomes
 * "1_2") and an interior U+00A0 becomes a space that splits the number in two,
 * so "1 5" is rejected rather than read as 15.
 *
 * The final digits-to-double step delegates to `Number()`, which the ECMAScript
 * spec requires to be correctly rounded — the same round-half-to-even result
 * `strtod` produces. Only pre-validated decimal literals ever reach it, so the
 * places `Number()` disagrees with Python (`Number("") === 0`,
 * `Number("0x10") === 16`, `Number("Infinity")`) are unreachable.
 */

import { decimalValue } from '../unicode/digits.mjs';
import { isUnicodeSpace, stripAsciiSpace } from '../unicode/whitespace.mjs';
import { PyValueError } from './errors.mjs';

/**
 * Grammar accepted after normalisation, underscore removal and trimming.
 * A mantissa needs at least one digit, on either side of the point; an
 * exponent, once introduced by e/E, needs at least one digit of its own —
 * which is why "1e" and "1e+" are errors rather than 1.0.
 */
const DECIMAL = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;
const INFINITY = /^[+-]?(?:inf|infinity)$/i;
const NOT_A_NUMBER = /^[+-]?nan$/i;

/** Stage 1: fold Unicode spaces and Nd digits down to ASCII. */
function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint < 0x7f) {
      out += character;
      continue;
    }
    if (isUnicodeSpace(codePoint)) {
      out += ' ';
      continue;
    }
    const value = decimalValue(codePoint);
    out += value >= 0 ? String(value) : character;
  }
  return out;
}

/**
 * Stage 2: PEP 515. An underscore is legal only when the character before it
 * and the character after it are both ASCII digits; survivors are removed.
 * Rejects "1__0.5", "_1.5", "1.5_", "1_.5" and "1._5"; accepts "1_000.5" and
 * "1.5e1_0".
 */
function removeUnderscores(text) {
  let out = '';
  let previous = '';
  for (const character of text) {
    if (character === '_') {
      if (!(previous >= '0' && previous <= '9')) return null;
    } else {
      if (previous === '_' && !(character >= '0' && character <= '9')) return null;
      out += character;
    }
    previous = character;
  }
  return previous === '_' ? null : out;
}

/**
 * Convert `text` to a double, or throw `ValueError` with CPython's wording.
 *
 * Out-of-range literals saturate rather than raise: "1e309" yields Infinity and
 * "1e-400" yields 0.0, matching `float()`.
 */
export function pyFloat(text) {
  const normalised = removeUnderscores(transformDecimalAndSpaceToAscii(text));
  const candidate = normalised === null ? null : stripAsciiSpace(normalised);

  if (candidate !== null && candidate !== '') {
    if (DECIMAL.test(candidate)) return Number(candidate);
    if (NOT_A_NUMBER.test(candidate)) return Number.NaN;
    if (INFINITY.test(candidate)) {
      return candidate[0] === '-' ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY;
    }
  }

  throw new PyValueError(`could not convert string to float: ${JSON.stringify(text)}`);
}

