/**
 * `repr()` of a Python `str`.
 *
 * argparse embeds the offending value in "invalid float value: %r", so error
 * text is only byte-exact if this matches CPython's `unicode_repr` precisely:
 *
 *   - single quotes by default; double quotes instead when the string contains
 *     an apostrophe but no double quote, so repr("a'b") is "a'b" in double
 *     quotes rather than an escaped apostrophe.
 *   - backslash always doubles; the active quote is backslash-escaped.
 *   - \t, \n and \r get their short forms; other non-printables use \xNN,
 *     \uNNNN or \UNNNNNNNN according to magnitude, with lowercase hex.
 *   - printable non-ASCII is emitted literally — Python 3 does not force ASCII.
 *
 * Lone surrogates (category Cs) reach here from surrogateescape-decoded argv
 * and print as \udcff, which is what the reference build shows for a byte that
 * is not valid UTF-8.
 */

import { isPrintableCodePoint } from '../unicode/printable.mjs';

const SHORT_ESCAPES = new Map([
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
  [0x5c, '\\\\'],
]);

function hexEscape(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * Iterate `text` by code point while still yielding lone surrogates as
 * themselves. The `for...of` protocol already does this — an unpaired
 * surrogate is returned as a single-unit string — so it is safe here.
 */
function* codePoints(text) {
  for (const character of text) yield character.codePointAt(0);
}

export function reprStr(text) {
  const hasSingle = text.includes("'");
  const hasDouble = text.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = quote;
  for (const codePoint of codePoints(text)) {
    if (codePoint === quoteCode) {
      out += `\\${quote}`;
      continue;
    }
    const short = SHORT_ESCAPES.get(codePoint);
    if (short !== undefined) {
      out += short;
      continue;
    }
    out += isPrintableCodePoint(codePoint) ? String.fromCodePoint(codePoint) : hexEscape(codePoint);
  }
  return out + quote;
}

