/**
 * `canonicaljson.encode_canonical_json` — the float path.
 *
 * The library builds on `json.dumps`, so numbers are rendered by
 * `float.__repr__` and the result is returned as `bytes`, not `str`. The one
 * behaviour that matters beyond formatting is the guard `json/encoder.py`
 * applies before writing: nan, inf and -inf are not representable in JSON, so
 * the encoder raises `ValueError` naming the offending value by its repr.
 *
 * That check is on the *value*, not the input text, which is why "1e309"
 * fails — `float()` saturates it to inf long before the encoder sees it — and
 * why "-nan" reports "nan", since a NaN carries no sign through repr.
 */

import { PyValueError } from '../python/errors.mjs';
import { reprFloat } from '../python/float-repr.mjs';

const UTF8 = new TextEncoder();

/** Serialise a float exactly as `json.dumps` would, without the JSON guard. */
export function encodeFloat(value) {
  return reprFloat(value);
}

/**
 * Encode `value` to canonical JSON bytes.
 *
 * Accepts the float domain this program exercises; anything else is out of
 * scope and reported rather than silently mis-encoded.
 */
export function encodeCanonicalJson(value) {
  if (typeof value !== 'number') {
    throw new TypeError(`unsupported type for canonical JSON: ${typeof value}`);
  }
  if (!Number.isFinite(value)) {
    throw new PyValueError(
      `Out of range float values are not JSON compliant: ${reprFloat(value)}`,
    );
  }
  return UTF8.encode(encodeFloat(value));
}

