/**
 * A faithful subset of `argparse.ArgumentParser`.
 *
 * Only the machinery this program's parser shape can reach is implemented — one
 * required long option with a `type=` converter, plus the automatic `-h` — but
 * within that scope the observable behaviour is reproduced rather than
 * approximated, because several of the quirks are surprising:
 *
 *   - `_negative_number_matcher` is `^-\d+$|^-\d*\.\d+$`. A value matching it is
 *     taken as a value; anything else beginning with "-" is read as an unknown
 *     option. So `--a -1.5` works but `--a -1e5`, `--a -1.` and `--a -inf` all
 *     fail with "expected one argument" — the value never reaches `float()`.
 *   - A lone "-" is not an option (length 1), so it *is* passed through and
 *     fails as an invalid float instead.
 *   - "--" and everything after it is forced to value position, and "--" is
 *     never accepted as an option's argument. With no positionals declared it
 *     ends up in the leftovers, hence "unrecognized arguments: --".
 *   - A value containing a space is treated as a value even when it starts with
 *     "-", which is the documented escape hatch for `--a " -1e5"`.
 *   - Errors fire in source order: value conversion during the scan, then the
 *     required-argument check, then unrecognised leftovers. `-h` is handled the
 *     moment it is reached, so `--help --a abc` prints help while
 *     `--a abc --help` reports the bad float.
 */

import { ArgumentTypeError, SystemExit } from './errors.mjs';
import { reprStr } from '../python/repr-str.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Terminal width argparse assumes when COLUMNS is unset, minus its margin. */
const HELP_WIDTH = 78;
const MAX_HELP_POSITION = 24;
const INDENT = 2;

class Action {
  constructor({ optionStrings, dest, kind, type, metavar, required, help }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.kind = kind; // 'store' | 'help'
    this.type = type;
    this.metavar = metavar;
    this.required = required ?? false;
    this.help = help ?? null;
  }

  /** `store` consumes exactly one argument; `help` consumes none. */
  get takesValue() {
    return this.kind === 'store';
  }

  /** How the action is spelled in the options list of `--help`. */
  formatInvocation() {
    if (!this.takesValue) return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${this.metavar}`).join(', ');
  }

  /** How the action is spelled in the usage line. */
  formatUsage() {
    const body = this.takesValue
      ? `${this.optionStrings[0]} ${this.metavar}`
      : this.optionStrings[0];
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  /**
   * @param {{prog: string}} options `prog` stands in for
   *   `os.path.basename(sys.argv[0])`, which is what appears in usage and error
   *   messages.
   */
  constructor({ prog }) {
    this.prog = prog;
    this.prefixChars = new Set(['-']);
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      kind: 'help',
      dest: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? optionStrings.at(-1).replace(/^-+/, '');
    const action = new Action({
      optionStrings,
      dest,
      kind: options.kind ?? 'store',
      type: options.type ?? ((value) => value),
      metavar: options.metavar ?? dest.toUpperCase(),
      required: options.required,
      help: options.help,
    });
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /**
   * True when any declared option string could itself be mistaken for a
   * negative number, which is what disables the negative-number escape hatch.
   */
  get hasNegativeNumberOptionals() {
    return [...this.optionStringActions.keys()].some((option) => NEGATIVE_NUMBER.test(option));
  }

  // ---------------------------------------------------------------- messages

  formatUsage() {
    const parts = this.actions.map((action) => action.formatUsage());
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => action.formatInvocation());
    const actionMaxLength = Math.max(...invocations.map((text) => text.length)) + INDENT;
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    let out = `${this.formatUsage()}\noptions:\n`;
    for (const [index, action] of this.actions.entries()) {
      const invocation = invocations[index];
      if (action.help === null) {
        out += `${' '.repeat(INDENT)}${invocation}\n`;
        continue;
      }
      const header = `${' '.repeat(INDENT)}${invocation.padEnd(actionWidth)}  `;
      out += `${header}${this.wrapHelp(action.help, helpPosition)}\n`;
    }
    return out;
  }

  /**
   * argparse rewraps help text to the remaining width. Nothing declared here is
   * long enough to wrap, but the width is honoured so the layout stays correct
   * if a longer help string is ever added.
   */
  wrapHelp(text, helpPosition) {
    const width = Math.max(HELP_WIDTH - helpPosition, 11);
    const lines = [];
    let current = '';
    for (const word of text.split(/\s+/)) {
      if (current === '') current = word;
      else if (`${current} ${word}`.length <= width) current += ` ${word}`;
      else {
        lines.push(current);
        current = word;
      }
    }
    if (current !== '') lines.push(current);
    return lines.join(`\n${' '.repeat(helpPosition)}`);
  }

  /** `parser.error()`: usage to stderr, then the message, then exit 2. */
  error(message) {
    throw new SystemExit(2, this.formatUsage() + `${this.prog}: error: ${message}\n`);
  }

  // ------------------------------------------------------------------ parsing

  /**
   * `_parse_optional`. Returns `null` when `argString` should be treated as a
   * value, or a tuple whose `action` is `null` for an unrecognised option.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.has(argString[0])) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null; // a bare "-" is a value

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const candidates = this.getOptionTuples(argString);
    if (candidates.length > 1) {
      const options = candidates.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (candidates.length === 1) return candidates[0];

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** `_get_option_tuples`: prefix matching for abbreviated options. */
  getOptionTuples(argString) {
    const results = [];
    const prefix = argString[0];

    if (argString.length > 1 && argString[1] === prefix) {
      let optionPrefix = argString;
      let explicitArg = null;
      const equals = argString.indexOf('=');
      if (equals !== -1) {
        optionPrefix = argString.slice(0, equals);
        explicitArg = argString.slice(equals + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          results.push({ action, optionString, explicitArg });
        }
      }
      return results;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        results.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        results.push({ action, optionString, explicitArg: null });
      }
    }
    return results;
  }

  /**
   * Classify every argument as 'O' (option) or 'A' (value), forcing "--" and
   * everything following it into value position.
   */
  classify(argStrings) {
    const patterns = [];
    const tuples = [];
    let afterDoubleDash = false;

    for (const argString of argStrings) {
      if (afterDoubleDash || argString === '--') {
        afterDoubleDash = true;
        patterns.push('A');
        tuples.push(null);
        continue;
      }
      const tuple = this.parseOptional(argString);
      patterns.push(tuple === null ? 'A' : 'O');
      tuples.push(tuple);
    }
    return { patterns, tuples };
  }

  /** Run `action.type` on `text`, reporting failure the way argparse does. */
  convert(action, optionString, text) {
    try {
      return action.type(text);
    } catch (cause) {
      if (cause instanceof ArgumentTypeError) {
        this.error(`argument ${optionString}: ${cause.message}`);
      }
      const typeName = action.type.typeName ?? action.type.name ?? 'value';
      this.error(`argument ${optionString}: invalid ${typeName} value: ${reprStr(text)}`);
    }
    return undefined; // unreachable: error() always throws
  }

  /**
   * `parse_args`. Returns the populated namespace, or throws `SystemExit` for
   * help and every error path.
   */
  parseArgs(argStrings) {
    const { patterns, tuples } = this.classify(argStrings);
    const namespace = Object.create(null);
    const seen = new Set();
    const extras = [];

    let index = 0;
    while (index < argStrings.length) {
      if (patterns[index] === 'A') {
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArg } = tuples[index];
      if (action === null) {
        extras.push(argStrings[index]);
        index += 1;
        continue;
      }

      if (!action.takesValue) {
        if (explicitArg !== null && explicitArg !== undefined) {
          this.error(`argument ${optionString}: ignored explicit argument ${reprStr(explicitArg)}`);
        }
        if (action.kind === 'help') {
          throw new SystemExit(0, null, this.formatHelp());
        }
        index += 1;
        continue;
      }

      let text;
      if (explicitArg !== null && explicitArg !== undefined) {
        text = explicitArg;
        index += 1;
      } else {
        const next = index + 1;
        // "--" is never harvested as an option's argument.
        const available = next < argStrings.length
          && patterns[next] === 'A'
          && argStrings[next] !== '--';
        if (!available) this.error(`argument ${optionString}: expected one argument`);
        text = argStrings[next];
        index += 2;
      }

      namespace[action.dest] = this.convert(action, optionString, text);
      seen.add(action);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.at(-1));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

