/**
 * Control-flow signals used by the argparse emulation.
 *
 * `parse_args` never returns on an error path — it calls `parser.error()`,
 * which prints usage and raises `SystemExit(2)`, or `-h`, which prints help and
 * raises `SystemExit(0)`. Modelling that as a thrown value keeps the parser
 * free of process-level concerns: it carries the text it wants written, and the
 * entry point decides which stream it lands on and when to exit.
 */

export class SystemExit extends Error {
  /**
   * @param {number} code process exit status
   * @param {?string} stderrText text to write to stderr before exiting
   * @param {?string} stdoutText text to write to stdout before exiting
   */
  constructor(code, stderrText = null, stdoutText = null) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
    this.stderrText = stderrText;
    this.stdoutText = stdoutText;
  }
}

/** Raised by a `type=` callable to reject a value; argparse reformats it. */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

