/**
 * Recovering `sys.argv` the way CPython sees it.
 *
 * Python decodes argv from bytes using the filesystem encoding with the
 * `surrogateescape` error handler (PEP 383), so a byte that is not valid UTF-8
 * survives as U+DC80+byte and reprs as e.g. "\udcff". Node has already lossily
 * decoded `process.argv` by the time user code runs — invalid bytes become
 * U+FFFD — so the original octets are read back from /proc/self/cmdline where
 * that interface exists.
 *
 * On platforms without procfs, or if anything about the readback looks
 * inconsistent, `process.argv` is used unchanged. That only costs fidelity for
 * arguments that were not valid UTF-8 to begin with.
 */

import { readFileSync } from 'node:fs';

/** Decode UTF-8 strictly, mapping every undecodable byte to U+DC00+byte. */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let index = 0;

  while (index < bytes.length) {
    const byte = bytes[index];

    if (byte < 0x80) {
      out += String.fromCharCode(byte);
      index += 1;
      continue;
    }

    let length;
    let codePoint;
    let lowerBound;
    if (byte >= 0xc2 && byte <= 0xdf) {
      length = 2;
      codePoint = byte & 0x1f;
      lowerBound = 0x80;
    } else if (byte >= 0xe0 && byte <= 0xef) {
      length = 3;
      codePoint = byte & 0x0f;
      lowerBound = 0x800;
    } else if (byte >= 0xf0 && byte <= 0xf4) {
      length = 4;
      codePoint = byte & 0x07;
      lowerBound = 0x10000;
    } else {
      out += String.fromCharCode(0xdc00 + byte); // 0xc0, 0xc1, 0xf5..0xff, stray continuation
      index += 1;
      continue;
    }

    let valid = index + length <= bytes.length;
    if (valid) {
      for (let offset = 1; offset < length; offset += 1) {
        const continuation = bytes[index + offset];
        if ((continuation & 0xc0) !== 0x80) {
          valid = false;
          break;
        }
        codePoint = (codePoint << 6) | (continuation & 0x3f);
      }
    }
    // Reject overlongs, UTF-16 surrogates and anything past U+10FFFF, so that
    // each offending byte is escaped individually as CPython does.
    if (!valid || codePoint < lowerBound || codePoint > 0x10ffff
      || (codePoint >= 0xd800 && codePoint <= 0xdfff)) {
      out += String.fromCharCode(0xdc00 + byte);
      index += 1;
      continue;
    }

    out += String.fromCodePoint(codePoint);
    index += length;
  }

  return out;
}

/** Split the NUL-delimited /proc/self/cmdline payload into argument buffers. */
function readProcCmdline() {
  const raw = readFileSync('/proc/self/cmdline');
  const parts = [];
  let start = 0;
  for (let index = 0; index < raw.length; index += 1) {
    if (raw[index] === 0) {
      parts.push(raw.subarray(start, index));
      start = index + 1;
    }
  }
  if (start < raw.length) parts.push(raw.subarray(start));
  return parts;
}

/**
 * The user-supplied arguments — everything after the executable and the script
 * — decoded with surrogateescape.
 */
export function getScriptArgs() {
  const fallback = process.argv.slice(2);
  try {
    const parts = readProcCmdline();
    if (parts.length < fallback.length) return fallback;
    const tail = parts.slice(parts.length - fallback.length);
    return tail.map((buffer) => decodeSurrogateEscape(buffer));
  } catch {
    return fallback;
  }
}

