/**
 * Synchronous stdout/stderr writing.
 *
 * `process.stdout.write` is asynchronous when the descriptor is a pipe, so text
 * queued immediately before `process.exit()` can be dropped. Writing through
 * `fs.writeSync` keeps output and exit status in the order a Python process
 * would produce them.
 */

import { writeSync } from 'node:fs';

const UTF8 = new TextEncoder();

function writeAll(fd, text) {
  if (text === null || text === '') return;
  const bytes = UTF8.encode(text);
  let offset = 0;
  while (offset < bytes.length) {
    try {
      offset += writeSync(fd, bytes, offset, bytes.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue; // non-blocking pipe: retry
      if (error.code === 'EPIPE') return; // reader went away, as SIGPIPE would
      throw error;
    }
  }
}

export function writeStdout(text) {
  writeAll(1, text);
}

export function writeStderr(text) {
  writeAll(2, text);
}

/** `print(value)` — the object's text followed by a single newline. */
export function print(text) {
  writeStdout(`${text}\n`);
}

