#!/usr/bin/env node
/**
 * Differential test harness: runs the same argv through the reference binary
 * and through test3.mjs, then compares stdout, stderr and exit code.
 *
 * The PyInstaller footer embeds the process id, which necessarily differs
 * between the two runs, so that one number is masked before comparing. Nothing
 * else is normalised.
 *
 *   node tools/difftest.mjs            # curated corpus
 *   node tools/difftest.mjs --random 3000
 */

import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PORT = path.join(HERE, '..', 'test3.mjs');
const REFERENCE = '/workspace/dataset/test3_executable';

const maskPid = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function run(command, argv) {
  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
    encoding: 'buffer',
    env: { ...process.env, TEST3_PROG: 'test3_executable' },
  });
  return {
    code: result.status,
    stdout: maskPid(result.stdout.toString('utf8')),
    stderr: maskPid(result.stderr.toString('utf8')),
  };
}

function compare(argv) {
  const expected = run([REFERENCE], argv);
  const actual = run([process.execPath, PORT], argv);
  const same = expected.code === actual.code
    && expected.stdout === actual.stdout
    && expected.stderr === actual.stderr;
  return { argv, expected, actual, same };
}

// ------------------------------------------------------------------- corpora

const CURATED = [
  // sample cases from the task
  ['--a', '-3.14159'], ['--a', '-1.23456789'], ['--a', '-0.001'], ['--a', '1.23456789'],
  // integral values and the trailing ".0"
  ['--a', '0'], ['--a', '-0'], ['--a', '0.0'], ['--a', '-0.0'], ['--a', '1'], ['--a', '-1'],
  ['--a', '100'], ['--a', '1e2'], ['--a', '1e10'], ['--a', '2'], ['--a', '10'],
  // the fixed / scientific cutoff on both ends
  ['--a', '1e14'], ['--a', '1e15'], ['--a', '1e16'], ['--a', '1e17'], ['--a', '1e21'],
  ['--a', '1e22'], ['--a', '9999999999999998'], ['--a', '1234567890123456'],
  ['--a', '12345678901234567'], ['--a', '123456789012345678'], ['--a', '9007199254740992'],
  ['--a', '9007199254740993'], ['--a', '1e-3'], ['--a', '1e-4'], ['--a', '1e-5'], ['--a', '1e-6'],
  ['--a', '0.0001'], ['--a', '0.00001'], ['--a', '0.001'], ['--a', '0.0000123'],
  // shortest round-trip digits
  ['--a', '0.1'], ['--a', '0.2'], ['--a', '0.3'], ['--a', '0.7'], ['--a', '1.1'], ['--a', '2.675'],
  ['--a', '4.35'], ['--a', '0.30000000000000004'], ['--a', '1.0000000000000002'],
  ['--a', '3.141592653589793238462643383279'], ['--a', '0.1000000000000000055511151231257827'],
  ['--a', '1.7976931348623157e308'], ['--a', '-1.7976931348623157e308'],
  ['--a', '2.2250738585072014e-308'], ['--a', '2.2250738585072011e-308'],
  ['--a', '5e-324'], ['--a', '4.9e-324'], ['--a', '1e-323'], ['--a', '-5e-324'],
  ['--a', '1e100'], ['--a', '1e-100'], ['--a', '1e308'], ['--a', '1e-308'],
  ['--a', '9.999999999999999e15'], ['--a', '1.0000000000000001e16'],
  ['--a', '0.00009999999999999999'],
  // non-finite: encoder raises
  ['--a', 'nan'], ['--a', 'NaN'], ['--a', 'NAN'], ['--a', 'inf'], ['--a', 'Inf'],
  ['--a', 'iNf'], ['--a', 'infinity'], ['--a', 'INFINITY'], ['--a', '1e309'], ['--a', '1e999'],
  ['--a=-inf'], ['--a=-nan'], ['--a=-infinity'], ['--a=-1e309'], ['--a', ' -inf'],
  ['--a', '1e-400'], ['--a', '-1e-400'],
  // float() grammar
  ['--a', '+1.5'], ['--a', '.5'], ['--a', '5.'], ['--a', '+.5'], ['--a', '-.5'],
  ['--a', '1E5'], ['--a', '1e+5'], ['--a', '1e-0'], ['--a', '5.e3'],
