  ['--a', '--'], ['--a', '-'], ['--a', 'nanx'], ['--a', 'infx'], ['--a', '1 5'],
  // whitespace handling
  ['--a', ' 1.5 '], ['--a', '\t1.5\n'], ['--a', '\r1.5\f'], ['--a', '\v1.5'],
  ['--a', ' 1.5'], ['--a', '1.5 '], ['--a', '　1.5'], ['--a', ' 1.5'],
  ['--a', ' 1.5'], ['--a', ' 1.5'], ['--a', '1.5'], ['--a', ' 1.5'],
  ['--a', '᠎1.5'], ['--a', '﻿1.5'], ['--a', '​1.5'], ['--a', '\x7f1.5'],
  ['--a', '\x1c1.5'], ['--a', '\x1f1.5'], ['--a', '1 5'],
  // unicode digits
  ['--a', '١٢٣'], ['--a', '٠.٥'], ['--a', '１２'],
  ['--a', '1.5e١٠'], ['--a', '١_٢'], ['--a', '\u{1d7cf}\u{1d7d0}'],
  ['--a', '\u{1d7d8}\u{1d7d9}'], ['--a', 'Ⅻ'], ['--a', '½'], ['--a', '༠'],
  // repr() of the rejected value
  ['--a', "a'b"], ['--a', 'a"b'], ['--a', 'a\'"b'], ['--a', 'a\\b'], ['--a', 'héllo'],
  ['--a', '日本'], ['--a', 'a\tb'], ['--a', 'a\nb'], ['--a', 'a\rb'],
  // argparse: the negative-number matcher
  ['--a', '-1'], ['--a', '-1.5'], ['--a', '-0.001'], ['--a', '-123'], ['--a', '-1.'],
  ['--a', '-1e5'], ['--a', '-1E5'], ['--a', '-inf'], ['--a', '-nan'], ['--a', '-1_000'],
  ['--a', '-abc'], ['--a', '-.'], ['--a', '-0.0'], ['--a', ' -1e5'], ['--a', '\t-1.5'],
  // argparse: = form
  ['--a=1.5'], ['--a=-1e5'], ['--a=-.5'], ['--a='], ['--a=abc'], ['--a=-1'],
  // argparse: structure
  [], ['--a'], ['-h'], ['--help'], ['-h', '-h'], ['--help', '--a', 'abc'],
  ['--a', 'abc', '--help'], ['--a', '1.5', '--b', '2'], ['--a', '1.5', 'extra'],
  ['--a', '1.5', '-x'], ['-a', '1.5'], ['--ab', '1.5'], ['--A', '1.5'], ['-x'],
  ['--a', '1.5', '--a', '2.5'], ['--a', '1', '--a', '2', '--a', '3'],
  ['--a', '1.5', '--'], ['--a', '--', '1.5'], ['--', '--a', '1.5'], ['--a', '1.5', '--', 'x'],
  ['-hx'], ['--help=x'], ['--a', '1.5', '--a'], ['1.5'], ['--a', '1.5', '1.5'],
];

/** Deterministic PRNG so a failing run can be reproduced exactly. */
function makeRandom(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

/** Values spanning every branch of the formatter, as text `float()` accepts. */
function randomCorpus(count, seed) {
  const random = makeRandom(seed);
  const buffer = new DataView(new ArrayBuffer(8));
  const cases = [];

  while (cases.length < count) {
    const kind = Math.floor(random() * 5);
    let value;
    if (kind === 0) {
      // uniform random bit patterns: subnormals, huge, tiny, negative zero
      buffer.setUint32(0, Math.floor(random() * 4294967296));
      buffer.setUint32(4, Math.floor(random() * 4294967296));
      value = buffer.getFloat64(0);
      if (!Number.isFinite(value)) continue;
    } else if (kind === 1) {
      value = (random() - 0.5) * 10 ** Math.floor(random() * 40 - 20);
    } else if (kind === 2) {
      value = Math.round((random() - 0.5) * 1e6) / 10 ** Math.floor(random() * 8);
    } else if (kind === 3) {
      value = Math.floor((random() - 0.5) * 2 ** 53);
    } else {
      value = (random() - 0.5) * 10 ** Math.floor(random() * 640 - 320);
      if (!Number.isFinite(value)) continue;
    }
    // toExponential(17) keeps the exact double while feeding the parser a
    // literal it has to round for itself.
    cases.push(['--a', value.toExponential(17)]);
  }
  return cases;
}

// ---------------------------------------------------------------------- main

const argv = process.argv.slice(2);
const randomIndex = argv.indexOf('--random');
const cases = randomIndex === -1
  ? CURATED
  : randomCorpus(Number(argv[randomIndex + 1] ?? 1000), Number(argv[randomIndex + 2] ?? 12345));

let failures = 0;
for (const testCase of cases) {
  const result = compare(testCase);
  if (result.same) continue;
  failures += 1;
  if (failures <= 30) {
    const show = (text) => JSON.stringify(text);
    console.log(`MISMATCH argv=${show(testCase)}`);
    console.log(`  exit   py=${result.expected.code} js=${result.actual.code}`);
    if (result.expected.stdout !== result.actual.stdout) {
      console.log(`  stdout py=${show(result.expected.stdout)} js=${show(result.actual.stdout)}`);
    }
    if (result.expected.stderr !== result.actual.stderr) {
      console.log(`  stderr py=${show(result.expected.stderr)}`);
      console.log(`         js=${show(result.actual.stderr)}`);
    }
  }
}

console.log(`\n${cases.length - failures}/${cases.length} matched, ${failures} mismatched`);
process.exit(failures === 0 ? 0 : 1);

