/**
 * Rendering an unhandled exception the way the frozen program does.
 *
 * The reference build is packaged with PyInstaller, so a crash produces a
 * CPython traceback followed by the bootloader's own footer. Three details
 * decide whether the output matches byte for byte:
 *
 *   - Source lines are not baked into the traceback; `linecache` reads them off
 *     disk at print time, relative to the *current working directory*. The
 *     bundled stdlib and site-packages ship as bytecode without their .py
 *     files, so those frames never show source — and the two test3.py frames
 *     only show source when a test3.py happens to be readable from the CWD.
 *     Run from the dataset directory the traceback is six lines longer than it
 *     is from anywhere else, and both forms are reproduced here.
 *   - The 3.11-style caret underline uses column offsets recorded in the code
 *     object, so they stay fixed even when linecache picks up a different file.
 *     Carets are suppressed when the marked span is no shorter than the
 *     stripped line, which is why `main()` never gets an underline but the
 *     `encode_canonical_json(...)` call does.
 *   - The number in "[PYI-1043:ERROR]" is the process id, reproduced from
 *     `process.pid`.
 */

import { readFileSync } from 'node:fs';

/**
 * Frames between the script entry and the raise.
 *
 * `colno`/`endColno` are the code object's column offsets for the
 * subexpression blamed by the traceback; frames without them are the bundled
 * modules, which have no source on disk to annotate.
 */
const FRAMES = [
  { file: 'test3.py', line: 15, name: '<module>', colno: 4, endColno: 10 },
  { file: 'test3.py', line: 11, name: 'main', colno: 13, endColno: 54 },
  { file: 'canonicaljson/__init__.py', line: 84, name: 'encode_canonical_json' },
  { file: 'json/encoder.py', line: 200, name: 'encode' },
  { file: 'json/encoder.py', line: 258, name: 'iterencode' },
];

/** Indent traceback frames use for their source line. */
const FRAME_INDENT = '    ';

/** Per-process memo, mirroring linecache's cache of file contents. */
const lineCache = new Map();

/** `linecache.getline` for a path resolved against the CWD; '' when absent. */
function getLine(file, lineNumber) {
  if (!lineCache.has(file)) {
    try {
      lineCache.set(file, readFileSync(file, 'utf8').split(/(?<=\n)/));
    } catch {
      lineCache.set(file, null);
    }
  }
  const lines = lineCache.get(file);
  if (lines === null) return '';
  return lines[lineNumber - 1] ?? '';
}

/**
 * The source line and optional caret underline for one frame, following
 * `traceback._format_frame_summary`.
 *
 * Column offsets are byte offsets in CPython; treating them as character
 * offsets is exact for the ASCII source this program ships with.
 */
function frameSource(frame) {
  if (frame.colno === undefined) return [];

  const original = getLine(frame.file, frame.line);
  const stripped = original.trim();
  if (stripped === '') return [];

  const lines = [`${FRAME_INDENT}${stripped}`];

  const strippedCharacters = original.length - original.trimStart().length;
  const start = frame.colno + 1;
  const end = frame.endColno + 1;

  // Carets are only drawn when they mark a strict subrange of the line.
  if (end - start < stripped.length) {
    const pad = Math.max(start - strippedCharacters - 1, 0);
    lines.push(`${FRAME_INDENT}${' '.repeat(pad)}${'^'.repeat(end - start)}`);
  }
  return lines;
}

/**
 * Format `error` as a complete stderr payload, footer included.
 *
 * @param {{pyType: string, pyMessage: string}} error
 * @param {number} pid value for the PyInstaller footer
 */
export function formatTraceback(error, pid) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of FRAMES) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    lines.push(...frameSource(frame));
  }
  lines.push(`${error.pyType}: ${error.pyMessage}`);
  lines.push(`[PYI-${pid}:ERROR] Failed to execute script 'test3' due to unhandled exception!`);
  return `${lines.join('\n')}\n`;
}

