/**
 * Rendering an unhandled exception the way the frozen program does.
 *
 * The reference build is packaged with PyInstaller, so a crash produces a
 * CPython traceback followed by the bootloader's own footer. Two details are
 * easy to miss:
 *
 *   - frames from the bundled stdlib and site-packages print their header line
 *     but no source line, because those modules ship as bytecode without the
 *     accompanying .py files. Only the two frames from the script itself show
 *     source, and the innermost of those carries the 3.11-style caret
 *     underline marking the failing subexpression.
 *   - the number in "[PYI-1043:ERROR]" is the process id, so it changes on
 *     every run and is reproduced here from `process.pid`.
 */

const SOURCE_LINE = '    result = canonicaljson.encode_canonical_json(data)'
  + '  # Encode float as canonical JSON';
const HIGHLIGHT = 'canonicaljson.encode_canonical_json(data)';

/** Caret underline positioned under `HIGHLIGHT` within `SOURCE_LINE`. */
function caretLine() {
  const column = SOURCE_LINE.indexOf(HIGHLIGHT);
  return `${' '.repeat(column)}${'^'.repeat(HIGHLIGHT.length)}`;
}

/** Call stack at the point `encode_canonical_json` rejects the value. */
const FRAMES = [
  { file: 'test3.py', line: 15, name: '<module>', source: ['    main()'] },
  { file: 'test3.py', line: 11, name: 'main', source: [SOURCE_LINE, caretLine()] },
  { file: 'canonicaljson/__init__.py', line: 84, name: 'encode_canonical_json', source: [] },
  { file: 'json/encoder.py', line: 200, name: 'encode', source: [] },
  { file: 'json/encoder.py', line: 258, name: 'iterencode', source: [] },
