/**
 * `_parse_optional`. Returns `null` when `argString` should be treated as a
 * value, or a tuple whose `action` is `null` for an unrecognised option.
 */
parseOptional(argString) {
  if (argString === '') return null;
  if (!this.prefixChars.has(argString[0])) return null;

  const exact = this.optionStringActions.get(argString);
  if (exact !== undefined) {
    return { action: exact, optionString: argString, explicitArg: null };
  }
  if (argString.length === 1) return null; // a bare "-" is a value

  const equals = argString.indexOf('=');
  if (equals !== -1) {
    const optionString = argString.slice(0, equals);
    const action = this.optionStringActions.get(optionString);
    if (action !== undefined) {
      return { action, optionString, explicitArg: argString.slice(equals + 1) };
    }
  }

  const candidates = this.getOptionTuples(argString);
  if (candidates.length > 1) {
    const options = candidates.map((tuple) => tuple.optionString).join(', ');
    this.error(`ambiguous option: ${argString} could match ${options}`);
  }
  if (candidates.length === 1) return candidates[0];

  if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
  if (argString.includes(' ')) return null;

  return { action: null, optionString: argString, explicitArg: null };
}

/** `_get_option_tuples`: prefix matching for abbreviated options. */
getOptionTuples(argString) {
  const results = [];
  const prefix = argString[0];

  if (argString.length > 1 && argString[1] === prefix) {
    let optionPrefix = argString;
    let explicitArg = null;
    const equals = argString.indexOf('=');
    if (equals !== -1) {
      optionPrefix = argString.slice(0, equals);
      explicitArg = argString.slice(equals + 1);
    }
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(optionPrefix)) {
        results.push({ action, optionString, explicitArg });
      }
    }
    return results;
  }

  const shortPrefix = argString.slice(0, 2);
  const shortExplicitArg = argString.slice(2);
  for (const [optionString, action] of this.optionStringActions) {
    if (optionString === shortPrefix) {
      results.push({ action, optionString, explicitArg: shortExplicitArg, sep: '' });
    } else if (optionString.startsWith(argString)) {
      results.push({ action, optionString, explicitArg: null });
    }
  }
  return results;
}

