/**
 * The source line and optional caret underline for one frame, following
 * `traceback._format_frame_summary`.
 *
 * Column offsets are byte offsets in CPython; treating them as character
 * offsets is exact for the ASCII source this program ships with.
 */
function frameSource(frame) {
  if (frame.colno === undefined) return [];

  const original = getLine(frame.file, frame.line);
  const stripped = original.trim();
